function settingsTabFromSearch(search = "") {
  const params = new URLSearchParams(search);
  if (params.get("diagnostics") === "1")
    return "diagnostics";
  if (params.get("settings") === "environment")
    return "environment";
  if (params.get("settings") === "diagnostics")
    return "diagnostics";
  if (params.get("settings") === "recovery" || params.get("safe") === "1" || params.get("skipStorage") === "1")
    return "recovery";
  return "general";
}
function shouldOpenSettingsFromSearch(search = "") {
  const params = new URLSearchParams(search);
  return params.get("settings") === "1" || Boolean(params.get("settings")) || params.get("diagnostics") === "1" || params.get("safe") === "1" || params.get("skipStorage") === "1";
}
